var n={en:`A monitoring dashboard updates every 5–10 seconds, with very few user commands. The team wants the simplest scalable transport.`,ua:`Панель моніторингу оновлюється кожні 5–10 секунд, команд від користувачів майже немає. Команда хоче найпростішого масштабованого транспорту.`};var t={en:[`Compare WebSocket, server-sent events and HTTP polling.`,`Draw authenticated requests and reconnection behavior.`,`Write ADR for proxy operation, latency and cost.`],ua:[`Порівняй WebSocket, SSE та HTTP polling.`,`Намалюй авторизовані запити й перепідключення.`,`Напиши ADR про проксі, затримку та вартість.`]};var o=[{en:`The transport fits actual one-way or two-way needs.`,ua:`Транспорт відповідає реальній потребі одно- чи двосторонності.`},{en:`Reconnect and access control are explicit.`,ua:`Перепідключення та права визначені.`}];var s={scenario:n,tasks:t,checks:o};export{o as checks,s as default,n as scenario,t as tasks};